positions = {"ENVIRONMENT": [(0.3, 0.8)], "MATERIAL": [(0.45, 0.75), (0.45, 0.7), (0.45, 0.65), (0.45, 0.6)], "METHOD": [(0.6, 0.75), (0.6, 0.7), (0.6, 0.65), (0.6, 0.6), (0.6, 0.55)], "PEOPLE": [(0.3, 0.2), (0.3, 0.25), (0.3, 0.3), (0.3, 0.35), (0.3, 0.4)], "MEASUREMENT": [(0.45, 0.25), (0.45, 0.3), (0.45, 0.35)], "MACHINE": [(0.6, 0.25), (0.6, 0.3)]}
